/* One encounter, one action strip and automatic process measurement. */
(()=>{
const time=x=>x?fmt(x):'Not documented',num=x=>x===null?'—':x.toFixed(1),attr=x=>esc(encodeURIComponent(x||'').replace(/'/g,'%27'));let pending=false;
function panel(d){const p=FNEncounter.project(d),ctx=fnDyn.encounterContext(),e=d.encounter||{},order=e.orderSets?.at(-1),valid=order&&order.inputRevision===d.revision&&order.protocolVersion===d.protocol.version;const clock=p.clock==='excluded'?'Excluded from first-dose target':p.clock==='dose_documented'?`First dose: ${num(p.doseMinutes)} min`:p.remaining===null?'Triage time unknown':p.remaining<0?`${num(-p.remaining)} min overdue`:`${num(p.remaining)} min remaining`;
return `<section class="panel encounter-panel" data-encounter-clock><div class="sectiontitle"><div><small class="intake-eyebrow">ENCOUNTER CONTROL · ${ctx.shared?'SHARED VISIT':'DEVICE REHEARSAL'}</small><h2>First-hour care & handoffs</h2><p>One record for this encounter. Suggested drafts, approvals and actual care remain distinct.</p></div><div class="encounter-clock ${p.clock==='overdue'||p.doseMinutes>60?'late':''}"><b data-clock-value>${esc(clock)}</b><span>60-minute first-dose target</span></div></div><div class="encounter-track">${p.milestones.map(m=>`<div class="${m.at?'done':''}"><small>${m.code}</small><b>${esc(m.label)}</b><span>${esc(time(m.at))}</span></div>`).join('')}</div><div class="encounter-next"><b>Next step</b><p>${p.doseId?(p.appropriate==='Unknown'?'Review first-dose appropriateness and continue reassessment.':'First-dose review recorded. Continue reassessment and result follow-up.'):!order?'Generate a suggested order-set draft, then review the physician plan.':!FNDynamic.currentPlan(d)?'Complete physician proposal and current pharmacy review.':!e.milestones?.ready?'Pharmacy: document when the drug is actually ready.':!p.doseId?'Nursing: document the actual administration.':'Review first-dose appropriateness and continue reassessment.'}</p><div class="actions">${['admin','physician'].includes(ctx.role)?`<button class="btn primary" onclick="FNEncounterUI.generate()">Generate order set</button><button class="btn" onclick="fnDyn.plan()">${d.proposal?'Review / revise plan':'Review physician plan'}</button><button class="btn" onclick="FNEncounterUI.milestone('order')">Document medication order time</button>`:''}${['admin','pharmacist'].includes(ctx.role)?`<button class="btn" onclick="fnDyn.pharmacy()" ${!d.proposal?'disabled title="Awaiting physician proposal"':''}>Pharmacy review</button><button class="btn" onclick="FNEncounterUI.milestone('ready')" ${!FNDynamic.currentPlan(d)?'disabled title="Current physician / pharmacy review required"':''}>Mark drug ready</button>`:''}${['admin','nurse'].includes(ctx.role)?`<button class="btn" onclick="fnDyn.dose()" ${!FNDynamic.currentPlan(d)?'disabled title="Current physician / pharmacy review required"':''}>${p.doseId?'Document additional dose':'Document first dose'}</button>`:''}${['admin','physician','pharmacist'].includes(ctx.role)?'<button class="btn" onclick="FNEncounterUI.review()">Eligibility & dose review</button>':''}</div></div>${order?`<details><summary>Saved order-set draft v${order.version} · ${valid?'current assessment':'historical context — regenerate'}</summary><p>Generated ${time(order.at)}. Unsigned draft; no order was transmitted and no administration is inferred.</p>${order.order.items.map(m=>`<p><b>${esc(m.name)}</b> · ${esc(m.initialDose)} · ${esc(m.route)} · ${esc(FNTherapyReview.frequency(m))}</p>`).join('')||'<p>No new initial dose suggested. Review ongoing therapy or missing safety data.</p>'}${order.order.holds.map(h=>`<p class="notice">${esc(h)}</p>`).join('')}</details>`:''}<details><summary>Measurement status · ${esc(p.group)}${p.outcome?' / '+esc(p.outcome):''}</summary><p>Actual dose time: ${time(d.tasks.find(t=>t.id===p.doseId)?.completedAt)}. Appropriateness: ${esc(p.appropriate)}.</p>${p.gaps.map(g=>`<p class="encounter-gap">${esc(g)}</p>`).join('')||'<p>No listed documentation gaps.</p>'}<p>Missing times are never credited as on-time care. A documented dose stops this timer; it only enters the numerator after explicit appropriateness review.</p></details></section>`;}
function form(title,body,submit){openDialog(title,`<form id="encounter-form">${body}<label class="field">Rationale / evidence<textarea name="note" required maxlength="800"></textarea></label><p id="dyn-form-error" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Save to this encounter</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`);document.querySelector('#encounter-form').onsubmit=ev=>{ev.preventDefault();submit(Object.fromEntries(new FormData(ev.target)))};}
function select(name,label,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></label>`}
function inbox(){if(!teamData||!teamSession?.signedIn)return '';const role=teamData.membership.role,uid=teamSession.userId,rows=teamData.visits.flatMap(v=>(v.snapshot.dynamic?.encounter?.notifications||[]).filter(n=>role==='admin'||n.roles.includes(role)).map(n=>({v,n}))).sort((a,b)=>Date.parse(b.n.createdAt)-Date.parse(a.n.createdAt)),open=rows.filter(x=>!x.n.acks[uid]);return `<section class="panel encounter-inbox"><div class="sectiontitle"><div><h2>Care alerts <span class="pill ${open.length?'amber':''}">${open.length} awaiting your acknowledgement</span></h2><p>Role-matched alerts from this shared workspace. Acknowledgement does not complete a clinical task.</p></div><button class="btn" onclick="fnMessages.open?fnMessages.open():go('Messages')">Notification settings</button></div>${open.slice(0,8).map(({v,n})=>{const log=teamData.events.find(x=>{if(x.action!=='CLINICAL_ALERT_DELIVERY')return false;try{return JSON.parse(x.note).notificationId===n.id}catch{return false}});let status='In-app record · push status unavailable';if(log){const r=JSON.parse(log.note);status=r.state==='push_service_accepted'?'Push service accepted · delivery not confirmed':r.state==='no_matching_staff'?'No matching approved staff recipient':'In-app alert · enable device notifications for push'}return `<article class="encounter-alert"><div><b>${esc(n.title)}</b><p>${esc(v.case_code)} · visit ${esc(v.id.slice(0,8))} · ${time(n.createdAt)}</p><small>${esc(status)}</small></div><div class="actions"><button class="btn primary" onclick="fnShell.patient('${attr(v.case_code)}','${attr(v.id)}','Care plan')">Open encounter</button><button class="btn" onclick="FNEncounterUI.ack('${attr(v.case_code)}','${attr(v.id)}','${attr(n.id)}')">Acknowledge</button></div></article>`}).join('')||'<p>No unacknowledged care alerts for your role.</p>'}${rows.length>8?'<p>Latest eight pending alerts shown. Open the encounter to review its full record.</p>':''}</section>`;}
function dashboard(){if(!teamSession?.signedIn||!teamData)return header('Encounter performance','Shared-visit measures from the same documented events.')+'<section class="panel"><p>Load your shared workspace to view encounter measures. Device-local training records are not combined with shared visits.</p><button class="btn primary" onclick="FNEncounterUI.load()">Load shared measurements</button></section>';const m=FNEncounter.summarize(teamData.visits);return header('Encounter performance','Automatic measures from shared encounters; no duplicate timing form.',`<button class="btn" onclick="FNEncounterUI.export()">Export encounter measures</button>`)+`<p class="notice">Synthetic workflow data only. ${m.untracked} shared visits have legacy documentation only; their known times are shown, but eligibility remains unresolved until reviewed after enrollment. Only the latest loaded 100 visits are available; this is not a whole-hospital rate.</p><div class="encounter-stats">${[['Appropriate first dose ≤60 min',m.percent===null?'—':m.percent.toFixed(1)+'%',m.numerator+' / '+m.denominator+' reviewed eligible encounters'],['Eligibility unresolved',m.unknown,m.excluded+' excluded · '+m.notEligible+' not eligible'],['Triage → dose',num(m.dose.median)+' min','Median · P90 '+num(m.dose.p90)+' min · n='+m.dose.n],['Result → decision',num(m.resultDecision.median)+' min','Median · P90 '+num(m.resultDecision.p90)+' min · n='+m.resultDecision.n]].map(([a,b,c])=>`<div><small>${a}</small><strong>${b}</strong><p>${c}</p></div>`).join('')}</div><section class="panel"><h2>Handoff delays</h2><div class="scroll"><table><thead><tr><th>Stage</th><th>Median min</th><th>P90 min</th><th>Valid pairs</th></tr></thead><tbody>${m.handoffs.map((h,i)=>`<tr><td>${['Triage → medication order','Order → pharmacy review','Pharmacy review → drug ready','Drug ready → first dose'][i]}</td><td>${num(h.median)}</td><td>${num(h.p90)}</td><td>${h.n}</td></tr>`).join('')}<tr><td>Result available → acknowledgement</td><td>${num(m.resultReview.median)}</td><td>${num(m.resultReview.p90)}</td><td>${m.resultReview.n}</td></tr></tbody></table></div><p>Missing or reversed timestamp pairs are excluded from interval distributions and remain visible as gaps in the encounter. They are never set to zero.</p></section><section class="panel"><h2>Encounter audit</h2><div class="scroll"><table><thead><tr><th>Patient / visit</th><th>Eligibility</th><th>Dose min</th><th>Metric result</th><th>Open</th></tr></thead><tbody>${m.rows.map(r=>`<tr><td>${esc(r.patientId)}<br>${esc(r.visitId.slice(0,8))}</td><td>${esc(r.group)}<br>${esc(r.reason)}</td><td>${num(r.doseMinutes)}</td><td>${esc(r.outcome||'Not in reviewed denominator')}</td><td><button class="btn" onclick="fnShell.patient('${attr(r.patientId)}','${attr(r.visitId)}','Care plan')">Open</button></td></tr>`).join('')}</tbody></table></div></section>`;}
window.FNEncounterUI={panel,dashboard,inbox,generate(){return fnDyn.encounterAction({action:'generate_order_set',note:'Generated suggested order-set draft for clinician review; no executable order issued'})},milestone(kind){const e=fnDyn.encounterContext().d.encounter||{};form(kind==='ready'?'Document drug readiness':'Document actual medication order',`<p>${kind==='order'?'Record when the medication was actually ordered in the prescribing workflow. Generating a suggested draft does not establish this time.':'Record actual preparation / availability, not the pharmacy approval time.'}</p><label class="field">Actual event time<input type="datetime-local" name="actualAt" value="${localInput(e.milestones?.[kind]?.actualAt||new Date().toISOString())}" required></label>`,v=>fnDyn.encounterAction({action:'record_milestone',kind,actualAt:new Date(v.actualAt).toISOString(),note:v.note}))},review(){const d=fnDyn.encounterContext().d,r=d.encounter?.measurementReview||{},dose=FNEncounter.firstDose(d);form('Eligibility & first-dose appropriateness',`<p>Triage, administration, regimen and reviewer identity come from this encounter. Review the clinical judgments below once; times do not need re-entry.</p><p><b>First documented dose:</b> ${esc(dose?.regimen||'Not documented')} · ${time(dose?.completedAt)}</p>`+select('cancerHistory','Cancer / treatment history confirmed',[['Unknown','Unknown'],['Yes','Yes'],['No','No']],r.cancerHistory||'Unknown')+select('exclusion','Exclusion review',[['none','No listed exclusion'],['prearrival_antibiotic','Antibiotic before triage'],['transferred_after_antibiotic','Transferred after antibiotics'],['comfort_only','Comfort-care-only plan']],r.exclusion||'none')+select('appropriate','Was the first documented regimen appropriate?',[['Unknown','Not yet determined'],['Yes','Yes — reviewed'],['No','No — reviewed']],r.appropriate||'Unknown'),v=>fnDyn.encounterAction({action:'review_measurement',...v}))},ack(pid,vid,nid){pid=decodeURIComponent(pid);vid=decodeURIComponent(vid);nid=decodeURIComponent(nid);fnDyn.context(pid,vid);form('Acknowledge care alert','<p>This records your acknowledgement. Review and complete the required clinical task separately.</p>',v=>fnDyn.encounterAction({action:'ack_notification',notificationId:nid,note:v.note}))},async load(){await refreshTeamWorkspace();go('Clinical quality')},export(){download('FN_shared_encounter_measures.json',{syntheticOnly:true,loadedAt:teamData?.serverTime,...FNEncounter.summarize(teamData?.visits||[])})}};
const oldQuality=clinicalQualityView;clinicalQualityView=function(){return (window.FNTTA?FNTTA.dashboard():dashboard())+`<details><summary>Separate legacy device-training measures</summary>${oldQuality()}</details>`};

// Keep the clock current without re-rendering an editing form or moving focus.
setInterval(()=>{if(document.hidden)return;const box=document.querySelector('[data-encounter-clock]');if(box){const d=fnDyn.encounterContext().d;if(d){const p=FNEncounter.project(d),node=box.querySelector('[data-clock-value]');if(node)node.textContent=p.clock==='excluded'?'Excluded from first-dose target':p.clock==='dose_documented'?'First dose: '+num(p.doseMinutes)+' min':p.remaining===null?'Triage time unknown':p.remaining<0?num(-p.remaining)+' min overdue':num(p.remaining)+' min remaining';box.querySelector('.encounter-clock')?.classList.toggle('late',p.clock==='overdue'||p.doseMinutes>60)}}},1000);
const oldRefresh=refreshTeamWorkspace;refreshTeamWorkspace=async function(silent=false){await oldRefresh(silent);if(pending||document.hidden||teamEditing||document.querySelector('#workflowDialog')||!teamData)return;const v=teamData.visits.find(v=>v.snapshot.dynamic&&FNEncounter.project(v.snapshot.dynamic).clock==='overdue'&&!v.snapshot.dynamic.encounter?.notifications?.some(n=>n.id==='first-dose-overdue'));if(!v)return;pending=true;try{await teamRequest('dynamic','POST',{id:v.id,revision:v.revision,operation:{action:'check_deadline',operationKey:'deadline-'+v.id,note:'Foreground shared-workspace deadline check'}});await oldRefresh(true)}catch{}finally{pending=false}};
setInterval(()=>{if(!document.hidden&&['Team workspace','Patient record','Clinical quality'].includes(view)&&!teamEditing&&!document.querySelector('#workflowDialog'))refreshTeamWorkspace(true).then(()=>{if(['Patient record','Clinical quality'].includes(view))render()})},10000);
})();
